// BMI270 体感手势识别（经 M5Unified 的 M5.Imu，不裸写寄存器）。
// 产出离散一次性事件 + 静止时长（供 main 判睡眠）。
#pragma once
#include <stdint.h>

enum class MotionEvent : uint8_t { None, PickedUp, Shaken };

class Motion {
public:
    void begin();                 // 探测 IMU 类型（自检日志用）
    void update(uint32_t dtMs);   // 每帧采样并判定
    MotionEvent event();          // 取走一次性事件（取走即清）
    uint32_t stillMs() const { return stillMs_; }
    bool imuOk() const { return imuOk_; }

private:
    bool imuOk_ = false;
    float lastMag_ = 1.0f;        // 上次加速度幅值（g）
    float activity_ = 0.0f;       // 低通平滑后的运动量
    uint32_t stillMs_ = 0;        // 连续静止时长
    MotionEvent pending_ = MotionEvent::None;
};

// IMU 读取逐字核对自 upstream（不凭记忆）:
//   M5.Imu.getType() / M5.Imu.update() / M5.Imu.getImuData().accel.x/y/z
//     ← m5stack/M5Unified examples/Basic/Imu/Imu.ino
//   M5Cardputer.begin() 已初始化内部 IMU；此处不重复 begin。
#include "motion.h"
#include "M5Cardputer.h"
#include <math.h>

namespace {
constexpr float MOVE_THRESH = 0.08f;            // g：超过算「在动」
constexpr float SHAKE_THRESH = 1.2f;            // g：单帧剧变算「晃动」（调高：需明显甩动才触发，避免轻碰/挪动误触晕）
constexpr uint32_t STILL_FOR_PICKUP = 1500;     // 静止≥此值后再动 = 拿起
}  // namespace

void Motion::begin() {
    imuOk_ = (M5.Imu.getType() != m5::imu_none);
    Serial.printf("[motion] imu type=%d ok=%d (bmi270 expected on ADV)\n",
                  static_cast<int>(M5.Imu.getType()), imuOk_ ? 1 : 0);
}

void Motion::update(uint32_t dtMs) {
    if (!imuOk_) return;
    if (!M5.Imu.update()) {  // 无新数据：累计静止
        stillMs_ += dtMs;
        return;
    }
    auto d = M5.Imu.getImuData();
    float mag = sqrtf(d.accel.x * d.accel.x +
                      d.accel.y * d.accel.y +
                      d.accel.z * d.accel.z);
    float delta = fabsf(mag - lastMag_);
    lastMag_ = mag;
    activity_ = activity_ * 0.7f + delta * 0.3f;  // 低通平滑

    if (delta > SHAKE_THRESH) {
        pending_ = MotionEvent::Shaken;
        stillMs_ = 0;
    } else if (activity_ > MOVE_THRESH) {
        if (stillMs_ > STILL_FOR_PICKUP) {        // 从静止/睡眠被拿起
            pending_ = MotionEvent::PickedUp;
        }
        stillMs_ = 0;
    } else {
        stillMs_ += dtMs;
    }
}

MotionEvent Motion::event() {
    MotionEvent e = pending_;
    pending_ = MotionEvent::None;
    return e;
}

// clawd 显示层（合成器）。四种模式合成到一块 240x135 sprite 后 push：
//   NORMAL   ：clawd GIF + 右上角会话计数角标
//   APPROVAL ：审批面板（工具+参数+按键提示），覆盖 GIF
//   SESSIONS ：只读会话列表
//   HELP     ：键位说明覆盖层
// 优先级 APPROVAL > SESSIONS > HELP > NORMAL。GIF 渲染逐字复用 buddy 家族 AnimatedGIF 思路。
#pragma once
#include "agent_state.h"
#include "link_state.h"   // BuddyState / SessionInfo（会话切换器用）
#include <stdint.h>

namespace clawd {
void begin();
bool ok();

// NORMAL 模式
void setState(AgentState s);              // 会话状态 → clawd GIF
void setBadge(int total, int running);    // 右上角 "T·R" 角标
void setBattery(int pct);                  // 顶栏电量 %（<0=unknown 不显示）。openspec cardputer-battery-indicator
// 多会话轮播：顶栏左显示当前会话标识 + [idx/total]；pinned=true 时底部钉态横幅。
// total<=0 或 tag 空 = 不显示（单聚合态）。openspec change cardputer-session-rotation。
void setSessionTag(const char* tag, int idx, int total, bool pinned);
void setToast(const char* text);          // 底部短暂提示(~1.5s,nudge 发送反馈)
void setSleeping(bool sleep);
void setOnline(bool on);                   // BLE 是否连上 cc-bridge；!on 时顶栏常驻 Connecting...
void reactHeart();
void reactDizzy();
void reactError();                        // 工具出错临时动画(error-120.gif, ~2.5s)

// APPROVAL 覆盖层
void showApproval(const char* tool, const char* hint);
void hideApproval();
bool approvalVisible();

// SESSIONS 覆盖层（per-session 可选中列表 → 物理 session 切换器）
void showSessions(const BuddyState& bs);  // 用 bs.sessions[] 渲染可选中列表
void hideSessions();
void sessionsMove(int delta);             // 移动选中项（viewport 跟随）
const char* sessionsSelectedSid();        // 当前选中会话的 sid（""=无）
bool sessionsVisible();

// QUESTION 覆盖层（AskUserQuestion 应答器）
void showQuestion(const BuddyState& bs);  // 用 bs.question 渲染选项面板（快照 rid+options+multi）
void hideQuestion();
void questionMove(int delta);             // 移动光标（viewport 跟随）
void questionToggle();                    // multiSelect: toggle 当前项勾选；单选: no-op
void questionJumpTo(int idx);             // 数字键直跳到第 idx 项（0-based）
bool questionMulti();                     // 是否 multiSelect
const char* questionRid();                // 当前问题 rid（""=无）
uint8_t questionSelectedIds(const char** out, uint8_t maxN);  // 收集提交 id（单选=光标项；多选=勾选项）
bool questionVisible();

// HELP 覆盖层（键位说明，h 键开关）
void showHelp();
void hideHelp();
bool helpVisible();

void tick(uint32_t dtMs);                 // 合成当前模式 → push
}

    if (tag) utf8lcpy(rotTag_, tag, sizeof(rotTag_)); else rotTag_[0] = 0;
    rotIdx_ = idx; rotTotal_ = total; rotPinned_ = pinned;
}
void setToast(const char* text) {
    strncpy(toast_, text ? text : "", sizeof(toast_) - 1);
    toast_[sizeof(toast_) - 1] = 0;
    toastMs_ = 1500;
}

void setSleeping(bool sleep) {
    if (sleep == sleeping_) return;
    sleeping_ = sleep;
    if (ready && mode_ == NORMAL) applyTarget();
}
// 纯存标志：GIF 由 main.cpp 的 setState 驱动，顶栏每 tick 重绘，无需在此重开 GIF。
void setOnline(bool on) { online_ = on; }
void reactHeart() { reactionFile_ = "heart.gif"; reactionMs_ = 1500; if (ready && mode_ == NORMAL) applyTarget(); }
void reactDizzy() { reactionFile_ = "dizzy.gif"; reactionMs_ = 1200; if (ready && mode_ == NORMAL) applyTarget(); }
// 工具出错：error 用 reaction 而非持久状态——"failed:" 后紧跟 done/ready 会一闪而过，
// reaction 临时覆盖 2.5s 保证 error 动画显示足够时长。

